// Server components only (node:fs).
import { readFileSync } from 'node:fs'
import { join } from 'node:path'

/**
 * Design v5 prototype data. Read on the server, per request, from committed files; nothing here computes a figure:
 *  - the API answers of the offline demo build (`e2e-shots/fixtures/<account>.json`, cut by `e2e-shots/cut-fixtures.ts`), the same
 *    bodies the QA scripts serve for `/audit/orders-summary`, `/audit/orders-ledger`, `/audit/v2`, `/audit/trades` and the replays;
 *  - the stored demo print windows (`backend/src/data/demoPrints.ts`, generated by `ml-service/scripts/cut_demo_prints.py`), the
 *    public Binance trades the production receipt shows.
 * The lab is 404 in production (`../../enabled.ts`), so reading files outside `app/` is acceptable here.
 */
export const ACCOUNTS = ['demo-moderate', 'demo-disciplined', 'demo-aggressive'] as const
export type AccountId = (typeof ACCOUNTS)[number]
export const ACCOUNT_LABEL: Record<AccountId, string> = {
  'demo-disciplined': 'Demo: limit orders, daytime',
  'demo-moderate': 'Demo: mixed orders, mixed hours',
  'demo-aggressive': 'Demo: market orders, night',
}

type Totals = Record<'execution' | 'spread' | 'impactTiming' | 'opportunity' | 'fees' | 'total', { usd: number; bps: number; n: number }>
export interface OrdersBody {
  available: boolean
  orders: { total: number; filled: number; partial: number; unfilled: number; open: number }
  shortfall: { n: number; unmeasured: number; totals: Totals }
  counts: { orders: number; withFills: number; fills: number; unrecorded: number }
  byType: Record<'all' | 'market' | 'limit', Totals>
  unfilledCost: { usd: number; count: number; measured: number }
  strip: { totalUsd: number; segments: Array<{ key: string; usd: number; share: number; below: number }> }
}
export interface LedgerOrder {
  key: string; orderId: string; symbol: string; side: string; type: string; status: string; placedAt: string; fills: number
  quantity: number; notionalUsd: number; feesUsd: number; makerShare: number | null; cost: { usd: number | null; bps: number | null }
}
export interface Trade {
  tradeId: string; orderId: string; symbol: string; side: string; executedAt: string; executionPrice: number; quantity: number
  notional: number; feeUsd: number | null; isMaker: boolean; dataSource: string; exchange: string
}
export interface V2Body {
  label: string; scoringVersion: string; integrityHash: string; demo?: { dataSource: string; basis: string }
  result: { grade: string; composite: number; band: [number, number]; orders: number; fills: number }
  costVsExpected: { n: number; paidUsd: number; expectedUsd: number; paidBps: number; expectedBps: number; excessBps: number; lowBps: number; highBps: number; insufficient: boolean; version: string }
}
export interface Replay {
  order: { orderId: string; symbol: string; exchange: string; type: string; side: string; quantity: number; executedQuantity: number; status: string; restingMs: number | null; createdAt: string; updatedAt: string }
  fills: Array<{ tradeId: string; time: string; price: number; quantity: number; notional: number; feeUsd: number | null; isMaker: boolean | null }>
  decomposition: Array<{ key: string; label: string; bps: number | null; usd: number | null; partOf?: string }>
  expectedCost: { applies: boolean; expectedBps: number | null; reason: string | null } | null
  sources: Array<{ label: string; sha256: string; url: string | null }>
  notes: string[]
}
export interface Account {
  id: AccountId; label: string; dataSource: string; ordersBody: OrdersBody; ledger: { counts: OrdersBody['counts']; orders: LedgerOrder[] }
  v2: V2Body; current: { fills: number; orders: number; notionalUsd: number; makerRatio: number }; trades: Trade[]; replays: Record<string, Replay>
}

const root = process.cwd()   // frontend/
export function loadAccount(id: string | undefined): Account {
  const acc = (ACCOUNTS as readonly string[]).includes(id ?? '') ? (id as AccountId) : 'demo-moderate'
  const f = JSON.parse(readFileSync(join(root, 'e2e-shots', 'fixtures', `${acc}.json`), 'utf8'))
  return { id: acc, label: ACCOUNT_LABEL[acc], dataSource: f.trades.trades[0]?.dataSource ?? f.v2Body.demo?.dataSource ?? 'unknown',
    ordersBody: f.ordersBody, ledger: f.ledger, v2: f.v2Body, current: f.current, trades: f.trades.trades, replays: f.replays }
}

export type Print = [aggId: number, tsMs: number, price: number, qty: number, isBuyerMaker: 0 | 1]
export interface PrintWindow { arrivalMs: number; fromMs: number; toMs?: number; fills: number[]; prints: Print[]; files?: Array<{ date: string; symbol: string; sha256: string }> }

/** The stored public-trade window of one demo order (null when the order has none: unfilled orders were not cut). */
export function loadPrintWindow(account: AccountId, orderId: string): PrintWindow | null {
  const src = readFileSync(join(root, '..', 'backend', 'src', 'data', 'demoPrints.ts'), 'utf8')
  const m = src.match(new RegExp(`'${account}': '((?:[^'\\\\]|\\\\.)*)'`))
  if (!m) return null
  const all = JSON.parse(m[1].replace(/\\'/g, "'")) as { windows: Record<string, PrintWindow> }
  return all.windows[orderId] ?? null
}
